patch:
--- <core>/platform/apple/Sources/XrayAppleClient/Debug/XrayProtocolDeviceProbe.swift	2026-10-17 12:28:34
+++ <campaign>/apple-sdk/Sources/XrayAppleClient/Debug/XrayProtocolDeviceProbe.swift	2026-10-18 18:33:56
@@ -87,6 +87,26 @@
                   labels.allSatisfy({ !$0.isEmpty && $0.utf8.count <= 63 && $0.utf8.allSatisfy {
                       (97...122).contains($0) || (48...57).contains($0) || $0 == 45
                   } }) else { throw Failure.configuration }
+            let redactionMarker = "NONSECRET-081-IMPORT-CONTROL"
+            let invalidVMess = try JSONSerialization.data(withJSONObject: [
+                "v": "2", "add": "127.0.0.1", "port": "443", "id": redactionMarker,
+                "aid": "0", "net": "tcp", "scy": "auto"])
+            let invalidProfiles: [(XrayProfileFormat, String)] = [
+                (.trojan, "trojan://\(redactionMarker)@[]:443"),
+                (.shadowsocks2022, "ss://2022-blake3-aes-128-gcm:\(redactionMarker)@127.0.0.1:443"),
+                (.vmess, "vmess://" + invalidVMess.base64EncodedString())]
+            for (format, input) in invalidProfiles {
+                var rejected = false
+                do { _ = try XrayProfileImporter.profile(from: input, format: format) }
+                catch {
+                    rejected = true
+                    guard !String(reflecting: error).contains(redactionMarker),
+                          !(error as NSError).localizedDescription.contains(redactionMarker)
+                    else { throw Failure.configuration }
+                }
+                guard rejected else { throw Failure.configuration }
+                emit(["event": "invalid-import-redaction", "format": format.rawValue, "result": "passed"])
+            }
             let info = XrayCore.ffiInfo
             emit(["event": "abi", "major": info.version.major, "minor": info.version.minor])
             try await cleanup()
